// === Uncler M Variant #4: Hyperdimensional Chaos Vortex & Solar Aura ===
// Inspired by OpenProcessing 2955184 'Unusual Globe' by u110137

const num = 180;
let counter = 0;
let mode = 0;
let ang, tang;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	colorMode(HSB, 360, 100, 100, 100);
	ang = createVector(0, 0, 0);
	tang = createVector(HALF_PI, 0, 0);
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

function draw() {
	let bEnergy = (window.beatEnergy || 0.0);
	let bassE = (window.bassEnergy || 0.0);
	let midE = (window.midEnergy || 0.0);
	let highE = (window.highEnergy || 0.0);

	counter += (2.0 + bassE * 5.0);
	if (frameCount % 90 === 0 && bEnergy > 0.5) {
		mode = (mode + 1) % 3;
	}

	tang.y = sin(frameCount * 0.025) * 2.0;
	tang.x = cos(frameCount * 0.02) * 1.8;
	ang.lerp(tang, 0.09);

	let m = 6 * TAU * cos(counter / 180) / num;
	orbitControl(0, 0, 0.5);
	rotateZ(ang.z + frameCount * 0.012);
	rotateY(ang.y);
	rotateX(ang.x);
	background(15, 95, 6);
	noFill();

	let scaleExpansion = 1.0 + bassE * 0.3;
	scale(scaleExpansion);

	for (let i = 0; i < min(num, frameCount); i++) {
		let a = i * PI / num;
		let r = sin(a) * min(width, height) / 2.2 * (1.0 + sin(i * 0.2 + frameCount * 0.1) * 0.08 * bassE);

		// Fiery Solar Gold HSL Palette
		let hueVal = (15 + i * 0.5 + bassE * 40) % 360;
		let satVal = 90 + sin(i * 0.04) * 10;
		let briVal = 85 + bEnergy * 15;
		stroke(hueVal, satVal, briVal, 85);
		strokeWeight(1.5 + (i % 4 === 0 ? 2.5 : 0) + bassE * 2.5);

		push();
		switch (mode) {
			case 0:
				rotateZ(2 * (i - num / 2) * m);
				break;
			case 1:
				rotateZ((i < num / 2) * PI);
				rotateY((i - num / 2) * m);
				break;
			case 2:
				rotateZ((i < num / 2) * PI);
				rotateX((i - num / 2) * m);
				break;
		}
		translate(0, 0, cos(a) * min(width, height) / 2.5);
		arc(0, 0, r, r, 0, PI * (1.0 + midE * 0.3), OPEN, 36);
		pop();
	}
}

if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
